#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STR_LEN 50000



char* removeCharFromArray(char* target, char* str) {
    int index = target - str;
    int new_size = strnlen(str, MAX_STR_LEN - (index + 1));

    for(int i = 0; i < new_size; ++i) {
        str[i] = str[(index + 1) + i];
    }
    str[new_size] = '\0';

    memset(str + new_size, 0, sizeof(char) * (MAX_STR_LEN - new_size));

    return str;
}


int lengthOfLongestSubstring(char* s) {
    if(s == NULL) { 
        return -1;  // when s is NULL
    }
    
    int s_len = strnlen(s, MAX_STR_LEN);

    if(s_len < 0 || s_len > 50000) {
        return -2;  // when s length is too small or big
    }
    if(s_len == 0 || s_len == 1) {
        return s_len;
    }
    
    char char_set[MAX_STR_LEN] = {0};
    char* c_loc = NULL;
    int char_set_len = 0;
    int max_length = 0;
    int left = 0;

    for(int right = 0; right < s_len; ++right) {
        if(char_set_len != 0) {
            c_loc = strchr(char_set, s[right]);
        }

        if(c_loc != NULL) {
            int old_char_set_len = char_set_len;

            removeCharFromArray(c_loc, char_set);
            char_set_len = strnlen(char_set, MAX_STR_LEN);

            left += old_char_set_len - char_set_len;
        }

        char_set[char_set_len] = s[right];
        char_set[char_set_len + 1] = '\0';

        int new_length = right - left + 1;
        max_length = new_length > max_length ? new_length : max_length;

        ++char_set_len;
    }

    return max_length;
}

